import{_ as n,A as s,o as c,c as i,j as t,a as d,C as o,X as a}from"./chunks/framework.pSp8ynCZ.js";const y=JSON.parse('{"title":"File and record format","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/docs/format.md","filePath":"format.md"}'),l={name:"rust/docs/format.md"};function u(h,e,p,m,f,b){const r=s("DocDiagram");return c(),i("div",null,[e[0]||(e[0]=t("h1",{id:"file-and-record-format",tabindex:"-1"},[d("File and record format "),t("a",{class:"header-anchor",href:"#file-and-record-format","aria-label":'Permalink to "File and record format"'},"​")],-1)),e[1]||(e[1]=t("p",null,[d("This page describes the current version-1 layouts. Use "),t("code",null,"format"),d(" parsing APIs instead of duplicating offset calculations in application code. Multi-byte integers and stored values use little-endian representation.")],-1)),e[2]||(e[2]=t("h2",{id:"matrix-stream-cpk",tabindex:"-1"},[d("Matrix stream: CPK "),t("a",{class:"header-anchor",href:"#matrix-stream-cpk","aria-label":'Permalink to "Matrix stream: CPK"'},"​")],-1)),e[3]||(e[3]=t("p",null,[d("A "),t("code",null,".cpk"),d(" stream has a 4096-byte superblock, page-aligned chunks, and a final chunk directory. Offsets are relative to the start of the stream, including when the stream is embedded inside another file.")],-1)),o(r,{name:"stream-layout"}),e[4]||(e[4]=a('<table tabindex="0"><thead><tr><th>Superblock offset</th><th>Field</th></tr></thead><tbody><tr><td>0</td><td>Four-byte magic <code>CPK\\0</code></td></tr><tr><td>4</td><td>Version <code>u16</code></td></tr><tr><td>6</td><td>Flags <code>u16</code>, currently zero</td></tr><tr><td>8</td><td>Page size <code>u32</code></td></tr><tr><td>12</td><td>Dtype code <code>u8</code></td></tr><tr><td>13</td><td>Source layout code <code>u8</code></td></tr><tr><td>14</td><td>Reserved <code>u16</code></td></tr><tr><td>16</td><td>Row count <code>u64</code></td></tr><tr><td>24</td><td>Column count <code>u32</code></td></tr><tr><td>28</td><td>Chunk count <code>u32</code></td></tr><tr><td>32</td><td>Target chunk rows <code>u32</code></td></tr><tr><td>36</td><td>Reserved <code>u32</code></td></tr><tr><td>40</td><td>Directory offset <code>u64</code></td></tr><tr><td>48</td><td>Stream length <code>u64</code></td></tr><tr><td>56</td><td>Non-cryptographic hash of the first 56 bytes and directory</td></tr></tbody></table><p>The writer starts with an invalid superblock and writes the valid one last. The hash protects header and directory consistency; it is not a cryptographic or whole-record payload integrity check.</p><p>Dtype codes, in order, are <code>U8, U16, U32, U64, I8, I16, I32, I64, F32, F64</code> (0 through 9). Source layout describes CSR or dense input. Neither dtype nor source layout determines an individual record&#39;s sparse/dense coding choice.</p><p>Each 40-byte directory entry contains:</p><table tabindex="0"><thead><tr><th>Field</th><th>Width</th></tr></thead><tbody><tr><td>First row</td><td>8 bytes</td></tr><tr><td>Chunk offset</td><td>8 bytes</td></tr><tr><td>Total chunk length</td><td>8 bytes</td></tr><tr><td>Metadata length</td><td>8 bytes</td></tr><tr><td>Row count</td><td>4 bytes</td></tr><tr><td>Reserved</td><td>4 bytes</td></tr></tbody></table><p>Chunks cover consecutive rows in order. The directory ends the stream.</p><h2 id="chunk-cpak" tabindex="-1">Chunk: CPAK <a class="header-anchor" href="#chunk-cpak" aria-label="Permalink to &quot;Chunk: CPAK&quot;">​</a></h2><p>A chunk begins with a 64-byte header using magic <code>CPAK</code> and version 1. Flags indicate a column permutation and column-mode values. The header declares row and column counts, value width, rANS lane settings, page size, row bounds, total nnz, metadata length, and record-region length.</p><p>Metadata then contains:</p><ol><li>Three 256-entry <code>u16</code> rANS frequency tables: gaps, ranks, and dictionaries. A used model sums to <code>2^11</code>; an unused one sums to zero.</li><li>An optional coded-to-source column permutation.</li><li>Optional per-column mode values.</li><li>Per-record offsets (<code>u64</code>), lengths (<code>u32</code>), and kind flags (<code>u8</code>).</li><li>A cumulative <code>u64</code> nnz table of <code>n_cells + 1</code> entries.</li><li>Padding before a page-aligned records region, when paged.</li></ol><p>Column ids use two bytes through 65536 dimensions and four bytes above that. Offsets and cumulative nnz tables are 8-byte aligned. Section offsets are derived from chunk shape rather than stored independently.</p><p>With <code>page_log2 = 0</code>, records are contiguous in row order. With paging enabled, the records region starts at a page boundary; records can appear in another physical order with gaps. The offset/length tables identify them. Supported packed page sizes are powers of two from 512 to 65536 bytes.</p><h2 id="record" tabindex="-1">Record <a class="header-anchor" href="#record" aria-label="Permalink to &quot;Record&quot;">​</a></h2><p>A nonempty record starts with:</p>',14)),o(r,{name:"record-layout"}),e[5]||(e[5]=a('<table tabindex="0"><thead><tr><th>Flag bits</th><th>Encoding</th></tr></thead><tbody><tr><td>0–1</td><td>Index mode: raw (0), gap-coded (1), dense (2)</td></tr><tr><td>2–3</td><td>Value mode: raw (0), dictionary-coded (1), column-mode-coded (2)</td></tr><tr><td>4–7</td><td>Reserved, zero</td></tr></tbody></table><p>A sparse record has stored elements in coded column order. Explicit stored zeros remain elements. A dense record has no index section and stores one value per dimension; its <code>nnz</code> counts nonzero values, while its element count is the full dimension. Empty rows can have a zero-length record.</p><p>Dictionary coding stores distinct value bit patterns and per-element ranks. Column-mode coding uses rank zero for that column&#39;s mode and positive ranks for exceptions in a record-local dictionary. rANS state capacity can carry leading escape or pool bytes; consumers should use the provided decoder rather than treating these as independent byte streams.</p><h2 id="parsing-and-ownership" tabindex="-1">Parsing and ownership <a class="header-anchor" href="#parsing-and-ownership" aria-label="Permalink to &quot;Parsing and ownership&quot;">​</a></h2><p><code>parse_meta</code> validates chunk-level structure and returns a borrowed view. <code>OwnedMeta</code> keeps owned bytes for longer-lived metadata. <code>Superblock</code> and <code>ChunkEntry</code> expose matrix-level fields. Record paths retain the trusted-data contract described in <a href="/cellpack-docs/rust/docs/codecs.html">codecs</a>; metadata validation is not validation of every inner record byte.</p><p>API: <a href="/cellpack-docs/rust/api/reference-format.html">format module</a>, <a href="/cellpack-docs/rust/api/generated-format-cpk-struct-Superblock.html">Superblock</a>, <a href="/cellpack-docs/rust/api/generated-format-cpk-struct-ChunkEntry.html">ChunkEntry</a>, <a href="/cellpack-docs/rust/api/generated-format-struct-Meta.html">Meta</a>.</p>',6))])}const k=n(l,[["render",u]]);export{y as __pageData,k as default};
